    int memo[11][25][21][2][2];
    int k_val;
    int dp(int idx, int diff, int rem, bool is_tight, bool started, const string& s) {
        if (idx == s.size()) return (started && diff == 10 && rem == 0) ? 1 : 0;
        if (memo[idx][diff][rem][is_tight][started] != -1) return memo[idx][diff][rem][is_tight][started];
