import java.util.*;

class Solution {
    private int[][][][][] memo;
    private int kVal;

    private int dp(int idx, int diff, int rem, boolean isTight, boolean started, String s) {
        if (idx == s.length()) return (started && diff == 10 && rem == 0) ? 1 : 0;
        int tIdx = isTight ? 1 : 0;
        int sIdx = started ? 1 : 0;
        if (memo[idx][diff][rem][tIdx][sIdx] != -1) return memo[idx][diff][rem][tIdx][sIdx];
        int limit = isTight ? (s.charAt(idx) - '0') : 9;
        int ans = 0;
        for (int d = 0; d <= limit; d++) {
            boolean nxtTight = isTight && (d == limit);
            if (!started) {
                if (d == 0) ans += dp(idx + 1, 10, 0, nxtTight, false, s);
                else {
                    int nd = 10 + (d % 2 == 0 ? 1 : -1);
                    ans += dp(idx + 1, nd, (rem * 10 + d) % kVal, nxtTight, true, s);
                }
            } else {
                int nd = diff + (d % 2 == 0 ? 1 : -1);
                ans += dp(idx + 1, nd, (rem * 10 + d) % kVal, nxtTight, true, s);
            }
        }
        return memo[idx][diff][rem][tIdx][sIdx] = ans;
    }

    private int countUpTo(int n) {
        if (n <= 0) return 0;
        String s = Integer.toString(n);
        memo = new int[s.length()][25][21][2][2];
        for (int[][][][] a : memo) for (int[][][] b : a) for (int[][] c : b) for (int[] d : c) Arrays.fill(d, -1);
        return dp(0, 10, 0, true, false, s);
    }

    public int numberOfBeautifulIntegers(int low, int high, int k) {
        kVal = k;
        return countUpTo(high) - countUpTo(low - 1);
    }
}

