var numberOfBeautifulIntegers = function(low, high, k) {
    function countUpTo(n) {
        if (n <= 0) return 0;
        const s = n.toString();
        const memo = new Map();
        function dp(idx, diff, rem, isTight, started) {
            if (idx === s.length) return (started && diff === 0 && rem === 0) ? 1 : 0;
            const key = `${idx},${diff},${rem},${isTight ? 1 : 0},${started ? 1 : 0}`;
            if (memo.has(key)) return memo.get(key);
            const limit = isTight ? Number(s[idx]) : 9;
            let ans = 0;
            for (let d = 0; d <= limit; d++) {
                const nxtTight = isTight && d === limit;
                if (!started) {
                    if (d === 0) ans += dp(idx + 1, 0, 0, nxtTight, false);
                    else {
                        const nd = diff + (d % 2 === 0 ? 1 : -1);
                        ans += dp(idx + 1, nd, (rem * 10 + d) % k, nxtTight, true);
                    }
                } else {
                    const nd = diff + (d % 2 === 0 ? 1 : -1);
                    ans += dp(idx + 1, nd, (rem * 10 + d) % k, nxtTight, true);
                }
            }
            memo.set(key, ans);
            return ans;
        }
        return dp(0, 0, 0, true, false);
    }
    return countUpTo(high) - countUpTo(low - 1);
};
